mapper.select:
SELECT
    material_code as materialCode,
    material_name as materialName
FROM material
WHERE material_group_id = #{materialGroupId}
ORDER BY material_name;

mapper.update:
UPDATE branch_stock
SET current_qty = current_qty - #{qty}
WHERE branch_code = #{branchCode} AND material_code = #{materialCode} AND current_qty >= #{qty}

UPDATE branch_stock
SET current_qty = current_qty + #{qty}
WHERE branch_code = #{branchCode} AND material_code = #{materialCode}

mapper.select:
SELECT branch_stock_code FROM branch_stock
WHERE branch_code = #{branchCode} AND material_code = #{materialCode}
LIMIT 1
